const container=document.querySelector("#project-articles");function formatDate(t){if(!t)return"";const e=new Date(t);return Number.isNaN(e.getTime())?"":e.toLocaleDateString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit"})}function renderArticles(t){if(!t||0===t.length)return void(container.style.display="none");let e="";for(const n of t){const t=formatDate(n.createdAt);e+=`\n      <a class="section-lab-panel" href="/notes/article/?id=${n.id}" style="text-decoration:none;color:inherit;">\n        <p class="section-lab-label">项目</p>\n        <h2>${n.title}</h2>\n        ${t?`<p style="font-size:0.82rem;color:var(--section-muted);margin-top:8px;">${t}</p>`:""}\n      </a>`}container.innerHTML=e}async function load(){try{const t=await fetch("/api/notion/articles?public=true&module=项目"),e=await t.json();t.ok&&renderArticles(e.articles)}catch{container.style.display="none"}}load();